function process8bit(val) {
    return processBits(val, 8);
}

function process16bit(val) {
    return processBits(val, 16);
}

function process32bit(val) {
    return processBits(val, 32);
}

// Common processor
function processBits(val, BIT_SIZE) {
    const binary = val.toString(2)
        .padStart(BIT_SIZE, '0')
        .split('')
        .reverse()
        .join('');

    const bitObject = {};
    for (let i = 0; i < BIT_SIZE; i++) {
        bitObject[i] = Number(binary[i]);
    }
    return bitObject;
}

// ----------- MAIN LOOP -------------

for (const key in input) {
    const val = Number(input[key]) >>> 0;

    // Get register type
    const regType = REGISTER_TYPE[key] || DEFAULT_TYPE;

    let bitObject;

    // Route to respective function block
    if (regType === 8) {
        bitObject = process8bit(val);
    } else if (regType === 16) {
        bitObject = process16bit(val);
    } else if (regType === 32) {
        bitObject = process32bit(val);
    } else {
        // fallback
        bitObject = process16bit(val);
    }

    result[key] = bitObject;
}

// ----------- OUTPUT -------------

msg.payload = result;
return msg;

