    node.error(` No DO data found for ${mode}.MCR.DO`);
    return null;
}

const DO = globalData.MCR.DO;

// -------------------------------
// Identify tag pair (_Open / _Close)
// -------------------------------
const openTag = `${tagName}_Open`;
const closeTag = `${tagName}_Close`;

if (!DO[openTag] || !DO[closeTag]) {
    node.error(` Tag pair not found: ${openTag} / ${closeTag}`);
    return null;
}

// -------------------------------
// Read current values
// -------------------------------
const openVal = DO[openTag].value ?? 0;
const closeVal = DO[closeTag].value ?? 0;

// -------------------------------
// Only act if a change is required
// -------------------------------
if (val === 1) { // CLOSE command
    if (closeVal === 1 && openVal === 0) {
        //node.status({ fill: "yellow", shape: "ring", text: `${tagName} already CLOSED` });
        return null;
    }
} else if (val === 0) { // OPEN command
    if (openVal === 1 && closeVal === 0) {
       // node.status({ fill: "yellow", shape: "ring", text: `${tagName} already OPEN` });
        return null;
    }
}

// -------------------------------
// Interlock logic and update
// -------------------------------
if (val === 1) {
    // CLOSE request
    DO[closeTag].value = 1;
    DO[openTag].value = 0;
    node.status({ fill: "green", shape: "dot", text: ` Closing ${tagName}` });
} else {
    // OPEN request
    DO[openTag].value = 1;
    DO[closeTag].value = 0;
    node.status({ fill: "green", shape: "dot", text: ` Opening ${tagName}` });
}

