function process8bit(val) {
    return processBits(val, 8);
}

function process16bit(val) {
    return processBits(val, 16);
}

function process32bit(val) {
    return processBits(val, 32);
}

// Common processor
function processBits(val, BIT_SIZE) {
    const binary = val.toString(2)
        .padStart(BIT_SIZE, '0')
        .split('')
        .reverse()
        .join('');

    const bitObject = {};
    for (let i = 0; i < BIT_SIZE; i++) {
        bitObject[i] = Number(binary[i]);
    }
    return bitObject;
}

